// Literal runs and backward copies, decoded once when the piece is mounted.
function decode(): Uint8Array {
  const packed = atob(DATA);
  const raw = new Uint8Array((meta.cols * meta.rows * 54) / 2);
  let src = 0, dst = 0;
  while (src < packed.length) {
    const tag = packed.charCodeAt(src++);
    if (tag < 128) {
      const count = tag + 1;
      for (let i = 0; i < count; i++) raw[dst++] = packed.charCodeAt(src++);
    } else {
      const count = tag - 128 + 4;
      const distance = packed.charCodeAt(src++) | (packed.charCodeAt(src++) << 8);
      for (let i = 0; i < count; i++) {
        raw[dst] = raw[dst - distance];
        dst++;
      }
    }
  }
  return raw;
}

export default function foxGirl(): Frame {
  const raw = decode();
  const frames: Uint8Array[] = [];
  const art: string[] = [];
  const cells = meta.cols * meta.rows;
  for (let f = 0; f < 54; f++) {
    const tones = new Uint8Array(cells);
    const lines: string[] = [];
    for (let y = 0; y < meta.rows; y++) {
      let line = "";
      for (let x = 0; x < meta.cols; x++) {
        const i = y * meta.cols + x;
        const pair = raw[f * (cells / 2) + (i >> 1)];
        const tone = i & 1 ? pair & 15 : pair >> 4;
        tones[i] = tone;
        line += RAMP[tone];
      }
      lines.push(line);
    }
    frames.push(tones);
    art.push(lines.join("\n"));
  }
  return (t, { color } = {}) => {
    const i = ((Math.floor(t * meta.fps) % frames.length) + frames.length) % frames.length;
    if (color) color.set(frames[i]);
    return art[i];
  };
}
